<?php
declare(strict_types=1);
 ?>
<section class="hero panel"><div><div class="eyebrow"><?=t('home.fleet_eyebrow')?></div><h1><?=t('home.all_services')?></h1><div class="sub"><?=t('home.service_events_count',['n'=>count($allServices)])?></div></div><div class="form-actions"><a class="btn" target="_blank" href="?print=all_history"><?=t('home.print_all')?></a><a class="btn2" target="_blank" href="?print=all_history&photos=1"><?=t('home.with_photos')?></a><a class="btn2" href="?export=all_xlsx"><?=t('home.all_to_excel')?></a></div></section>
<section class="section panel"><?php if(!$allServices):?><div class="empty"><?=t('home.no_services')?></div><?php else:foreach($allServices as $s):?><details class="servicebox"><summary><div class="service-title"><div><strong><?=h(carName($s))?> · <?=h($s['title'])?></strong><?php if(($s['service_type']??'')&&serviceTypeLabel((string)$s['service_type'])!==$s['title']):?> <span class="badge"><?=h(serviceTypeLabel((string)$s['service_type']))?></span><?php endif;?><div class="tiny"><?=h(fiDate($s['service_date']))?> · <?=h(recordedKm((int)$s['odometer']))?><?=!empty($s['gap']['text'])?' · '.t('home.since_previous_service',['gap'=>h($s['gap']['text'])]):''?></div></div><span class="badge"><?=t('home.work_count',['n'=>count($s['actions'])+count($s['custom_actions'])])?><?=!empty($s['photos'])?' · '.t('home.photo_count',['n'=>count($s['photos'])]):''?></span></div></summary><div class="servicebody"><div class="chips"><?php foreach($s['actions'] as $a):?><span class="chip"><?=h($a['label'])?></span><?php endforeach;?><?php foreach($s['custom_actions'] as $a):?><span class="chip"><?=h($a['description'])?></span><?php endforeach;?></div><?php foreach($s['actions'] as $a):?><div class="kv"><span><?=h($a['label'])?></span><span><?=h(actionIntervalText($a))?></span></div><?php endforeach;?><?php if(!empty($s['mechanic_name_snapshot'])):?><div class="tiny" style="margin-top:9px"><?=t('home.mechanic',['name'=>h(mechanicLabel($s['mechanic_name_snapshot']))])?></div><?php endif;?><?php if(!empty($s['photos'])):?><div class="photo-grid"><?php foreach($s['photos'] as $ph):?><div class="photo-card"><a href="<?=h(photoUrl((int)$ph['id'],'original'))?>" target="_blank"><img loading="lazy" src="<?=h(photoUrl((int)$ph['id'],'thumb'))?>" alt="<?=t('home.service_photo')?>"></a><?php if(trim((string)($ph['caption']??''))!==''):?><div class="photo-caption"><?=h($ph['caption'])?></div><?php endif;?></div><?php endforeach;?></div><?php endif;?><div class="form-actions"><a class="btn2" href="?car=<?=(int)$s['car_id']?>&edit_service=<?=(int)$s['id']?>#huolto"><?=t('home.edit')?></a><a class="btn2" target="_blank" href="?print=service&service=<?=(int)$s['id']?>"><?=t('home.service_page')?></a><?php if(!empty($s['photos'])):?><a class="btn2" target="_blank" href="?print=service&service=<?=(int)$s['id']?>&photos=1"><?=t('home.with_photos')?></a><?php endif;?></div></div></details><?php endforeach;endif;?></section>
